const $=s=>document.querySelector(s),types={instant:'即时表达',workplace:'职场沟通',precision:'精准表达',advanced:'进阶表达'},dimensions={topic:'细分类别',scene:'使用场景',form:'语言形式'};
let lessons=[],learning={},natives={},current='',page=0,state={},view='home',nativeFilter='',history=[],historyIndex=-1,historyScope='',tagFilters={scene:'',form:''},englishVersion='casual';
try{state=JSON.parse(localStorage.getItem('english-reflex-v2')||'{}')}catch{}
for(const value of Object.values(state))if(value&&typeof value==='object'&&value.done===true&&value.marked===undefined){value.marked=true;value.markedAt=0;}
function save(){try{localStorage.setItem('english-reflex-v2',JSON.stringify(state));return true}catch{$('#status').textContent='此浏览器未允许本地保存。';return false}}
function currentLesson(){return lessons.find(l=>l.id===current)}
function filters(){return {type:$('#typeFilter').value,topic:$('#topicFilter').value,scene:tagFilters.scene,form:tagFilters.form,progress:$('#progress').value,native:nativeFilter}}
function filtered(exclude=''){const f=filters();return lessons.filter(l=>(exclude==='type'||!f.type||l.type===f.type)&&(!f.native||l.nativeId===f.native)&&Object.keys(dimensions).every(d=>exclude===d||!f[d]||l.tags[d].includes(f[d]))&&(!f.progress||state[l.id]?.marked)).sort((a,b)=>view==='browse'?(Number(!!state[b.id]?.marked)-Number(!!state[a.id]?.marked)||((state[b.id]?.marked?state[b.id].markedAt||0:0)-(state[a.id]?.marked?state[a.id].markedAt||0:0))):0)}
function updateFacets(){for(const [d,label] of Object.entries(dimensions)){const select=$('#'+d+'Filter');if(!select)continue;const selected=select.value,counts={};for(const l of filtered(d))for(const tag of l.tags[d])counts[tag]=(counts[tag]||0)+1;select.replaceChildren(new Option('全部'+label,''));for(const value of [...new Set([...Object.keys(counts),...(selected?[selected]:[])])].sort((a,b)=>a.localeCompare(b,'zh-CN')))select.add(new Option(`${value} (${counts[value]||0})`,value));select.value=selected;}}
function resetFilters(){for(const id of ['typeFilter','topicFilter','progress'])$('#'+id).value='';nativeFilter='';tagFilters={scene:'',form:''};page=0;}
function navigate(next){view=next;$('#home').hidden=view!=='home';$('#workspace').hidden=view==='home';$('#browseControls').hidden=view!=='browse';document.querySelectorAll('.card-edge-button').forEach(b=>b.hidden=view==='browse');$('#trainingLayout').classList.toggle('focused',view==='practice');$('#browseFromPractice').hidden=false;window.scrollTo({top:0,behavior:'instant'});}
function browse(defaults=false){if(defaults){resetFilters();$('#progress').value=lessons.some(l=>state[l.id]?.marked)?'marked':'';}if(view!=='browse'){current='';page=0;}navigate('browse');render();}
function start(type){resetFilters();$('#typeFilter').value=type;navigate('practice');const pool=filtered();current=pool[0]?.id||'';render();}
function browseTag(d,value){resetFilters();if(d==='topic'){$('#topicFilter').add(new Option(value,value));$('#topicFilter').value=value}else tagFilters[d]=value;current='';browse();}
function browseNative(id,type=''){resetFilters();nativeFilter=id;$('#typeFilter').value=type;current='';browse();}
function button(text,onClick,className=''){const b=document.createElement('button');b.type='button';b.textContent=text;b.className=className;b.onclick=onClick;return b;}
function renderActiveFilters(){const f=filters(),el=$('#activeFilters');el.replaceChildren();if(nativeFilter)el.append(button('相关表达：'+natives[nativeFilter].title+' ×',()=>{nativeFilter='';page=0;render()}));for(const [d,label]of Object.entries(dimensions))if(f[d])el.append(button(label+'：'+f[d]+' ×',()=>{if(d==='topic')$('#topicFilter').value='';else tagFilters[d]='';page=0;render()}));if(f.type||f.progress||f.native||f.topic||f.scene||f.form)el.append(button('清除筛选',()=>{resetFilters();current='';render()}));}
function syncNavigation(all){const scope=JSON.stringify(filters());if(scope!==historyScope){history=[];historyIndex=-1;historyScope=scope}if(current&&history[historyIndex]!==current){history=history.slice(0,historyIndex+1);history.push(current);historyIndex=history.length-1}const position=all.findIndex(l=>l.id===current)+1;document.querySelectorAll('.practice-position').forEach(el=>{el.textContent=`(${position}/${all.length})`;el.setAttribute('aria-label',`当前第 ${position} 条，共 ${all.length} 条`)});document.querySelectorAll('[data-practice-action]').forEach(b=>b.disabled=all.length<2);}
function render(){if($('#progress').value==='marked'&&!lessons.some(l=>state[l.id]?.marked))$('#progress').value='';updateFacets();const all=filtered();if(!all.some(l=>l.id===current))current=all[0]?.id||'';const l=currentLesson();page=Math.max(0,Math.min(page,Math.ceil(all.length/15)-1));$('#nav').replaceChildren(...all.slice(page*15,page*15+15).map(x=>{const b=button('',()=>{current=x.id;render()},x.id===current?'active':'');const title=document.createElement('span');title.textContent=x.short;const meta=document.createElement('small');meta.textContent=types[x.type]+' · '+x.sub+(state[x.id]?.marked?' · 已标记':'');b.append(title,meta);return b}));$('#count').textContent=`${all.length} 则练习`;$('#pageInfo').textContent=all.length?`${page+1} / ${Math.ceil(all.length/15)}`:'0 / 0';$('#prevPage').disabled=page===0;$('#nextPage').disabled=(page+1)*15>=all.length;$('#empty').hidden=!!l;$('#exercise').hidden=!l;renderActiveFilters();syncNavigation(all);if('speechSynthesis' in window)window.speechSynthesis.cancel();if($('#learningDialog').open)$('#learningDialog').close();if($('#exportDialog').open)$('#exportDialog').close();if(!l)return;
const native=natives[l.nativeId],unit=learning[l.id],workplace=l.type==='workplace',instant=l.type==='instant',precision=l.type==='precision',advanced=l.type==='advanced';$('#category').textContent=types[l.type];
$('#entryTags').replaceChildren(...Object.entries(dimensions).flatMap(([d,label])=>l.tags[d].map(value=>{const b=button(value,()=>browseTag(d,value),'tag-chip');b.title=label+'：'+value;return b})));
const siblings=lessons.filter(x=>x.nativeId===l.nativeId);$('#relatedEntries').replaceChildren();if(siblings.length>1){const label=document.createElement('small');label.textContent='同源词条';$('#relatedEntries').append(label,...Object.entries(types).filter(([key])=>siblings.some(x=>x.type===key)).map(([key,name])=>button(name+' '+siblings.filter(x=>x.type===key).length,()=>browseNative(l.nativeId,key),key===l.type?'related-current':'')));}
$('#sceneLabel').textContent=instant?'表达':'场景';$('#sceneLabel').hidden=!!l.picture;$('#context').hidden=!!l.picture;$('#picturePrompt').hidden=!l.picture;if(l.picture){$('#pictureImage').src=l.picture.src;$('#pictureImage').alt=l.picture.alt;}$('#answerTitle').textContent=l.picture?'答案':'英文表达';$('#context').textContent=instant?l.suggestion:l.context;$('#questionLabel').hidden=!workplace;$('#cn').hidden=!workplace;$('#cn').textContent=l.cn;$('#planning').hidden=!workplace;$('#planning').open=false;$('#reason').textContent=l.reason||'';$('#advancedPrompt').hidden=!advanced;if(advanced){$('#advancedChinese').textContent=l.suggestion;renderBase(l);}$('#precisionPrompt').hidden=!precision||!!l.picture;if(precision&&!l.picture){$('#precisionChinese').textContent=l.suggestion;$('#precisionCloze').textContent=l.cloze.sentenceEn;$('#precisionHint').textContent='补全“'+l.cloze.hintZh+'”';}$('#chinesePanel').hidden=!workplace;$('#chinesePanel').open=false;$('#revealActions').hidden=workplace;$('#workEnglishActions').hidden=!workplace;$('#suggestion').textContent=l.suggestion;$('#answer').hidden=true;$('#reveal').textContent='看英文表达';if(advanced)$('#reveal').textContent='看进阶表达';if(l.picture)$('#reveal').textContent='看答案';$('#reveal').setAttribute('aria-controls','answer');$('#reveal').setAttribute('aria-expanded','false');$('#revealEnglish').textContent='看英文表达';$('#revealEnglish').setAttribute('aria-expanded','false');$('.version-tabs').hidden=!workplace;$('#casualLabel').hidden=!workplace;
applyVersion('casual');renderEnglish(l,unit);
$('#explain').textContent=l.explain.replace(/这句本身是中性表达，可用于专业和一般对话；两版相同时无需刻意改写。/g,'').trim();$('#variant').textContent=(l.originalEquivalent&&l.type!=='advanced'?'原笔记 Equivalent：'+l.originalEquivalent+'。\n':'')+l.variant;$('#fix').textContent=l.fix;for(const id of ['explain','variant','fix'])addEnglishSpeech($('#'+id));setNote('explain');setStudy('meaning');if(unit){for(const [id,key]of [['learnTerm','term'],['learnMeaning','meaning'],['learnExample','example'],['learnExampleCn','exampleCn'],['learnForms','forms'],['learnAlternatives','alternatives']])$('#'+id).textContent=unit[key]||'';addSpeech($('#learnTerm'),unit.term);addSpeech($('#learnExample'),unit.example);for(const id of ['learnForms','learnAlternatives'])addEnglishSpeech($('#'+id));$('#learnPronunciation').textContent=unit.pronunciation||'';$('#learnPronunciation').hidden=!unit.pronunciation;}
updateBookmark();$('#status').textContent='';}
function applyVersion(version){englishVersion=version==='professional'?'professional':'casual';for(const v of ['professional','casual']){$('#'+v+'Panel').hidden=v!==englishVersion;$('#'+v+'Tab').setAttribute('aria-pressed',String(v===englishVersion))}}
function renderBase(l){const el=$('#advancedBase'),c=l.comparison,[a,b]=c.highlight;el.replaceChildren(document.createTextNode(c.sentenceEn.slice(0,a)));const phrase=document.createElement('u');phrase.className='equivalent-underline';phrase.textContent=c.sentenceEn.slice(a,b);el.append(phrase,document.createTextNode(c.sentenceEn.slice(b)));addSpeech(el,c.sentenceEn);}
function renderEnglish(l,unit){for(const version of ['pro','casual']){const target=$('#'+version),sentence=l.picture?unit.term:l[version],ranges=l.picture?[[0,unit.term.length]]:(l.learningHighlights?.[version]||[]);target.replaceChildren();let cursor=0;for(const [start,end] of ranges){target.append(document.createTextNode(sentence.slice(cursor,start)));const b=button(sentence.slice(start,end),()=>{if(!unit)return;setStudy('meaning');$('#learningDialog').showModal()},'expression-highlight');b.setAttribute('aria-haspopup','dialog');b.setAttribute('aria-controls','learningDialog');b.setAttribute('aria-label','学习表达：'+b.textContent);target.append(b);cursor=end;}target.append(document.createTextNode(sentence.slice(cursor)));addSpeech(target,sentence);}}
function addSpeech(el,text){if(!text?.trim())return;const b=button('',()=>speak(text,b),'speak-button');b.innerHTML='<svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5Zm4 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>';b.setAttribute('aria-label','朗读：'+text);b.title='朗读英文';el.append(b);}
function speak(text,b){if(!('speechSynthesis' in window)){b.title='此浏览器不支持朗读';$('#status').textContent='此浏览器不支持朗读，请使用支持语音的浏览器。';return}window.speechSynthesis.cancel();document.querySelectorAll('.speak-button').forEach(x=>x.classList.remove('speaking'));const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.9;const voices=window.speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='en-US'&&v.localService)||voices.find(v=>v.lang==='en-US')||voices.find(v=>v.lang.startsWith('en'))||null;b.classList.add('speaking');const end=()=>b.classList.remove('speaking');u.onend=end;u.onerror=e=>{end();if(e.error!=='interrupted'&&e.error!=='canceled'){$('#status').textContent='朗读未能播放，请检查设备声音或稍后重试。';b.title='朗读未能播放，点击重试'}};window.speechSynthesis.speak(u);}
function addEnglishSpeech(el){const text=el.textContent;el.replaceChildren();const re=/[A-Za-z][A-Za-z0-9’'.,!?;:() /—–+\-]*(?:[A-Za-z0-9.!?])/g;let cursor=0;for(const m of text.matchAll(re)){el.append(document.createTextNode(text.slice(cursor,m.index)+m[0]));if(m[0].trim().length>2)addSpeech(el,m[0].trim());cursor=m.index+m[0].length}el.append(document.createTextNode(text.slice(cursor)));}
function setStudy(key){for(const k of ['meaning','example','forms','alternatives']){$('#'+k+'Study').hidden=k!==key;$('#'+k+'Tab').setAttribute('aria-pressed',String(k===key));}}
function setNote(key){for(const k of ['explain','variant','fix']){$('#'+k).hidden=k!==key;$('#'+k+'NoteTab').setAttribute('aria-pressed',String(k===key));}}
function toggleEnglish(b){const show=$('#answer').hidden;$('#answer').hidden=!show;b.textContent=currentLesson().type==='advanced'?(show?'收起进阶表达':'看进阶表达'):currentLesson().picture?(show?'收起答案':'看答案'):(show?'收起英文表达':'看英文表达');b.setAttribute('aria-expanded',String(show));}
$('#reveal').onclick=()=>toggleEnglish($('#reveal'));
$('#revealEnglish').onclick=()=>toggleEnglish($('#revealEnglish'));
function changePractice(action){const all=filtered();if(all.length<2)return;const i=all.findIndex(x=>x.id===current);if(action==='random'){const others=all.filter(x=>x.id!==current);current=others[Math.floor(Math.random()*others.length)].id}else current=all[(i+(action==='previous'?-1:1)+all.length)%all.length].id;page=Math.floor(all.findIndex(x=>x.id===current)/15);render();$('.practice-column').scrollIntoView({block:'start',behavior:'instant'});}

function log(l){const n=natives[l.nativeId],u=learning[l.id];return `### ${new Date().toLocaleDateString('sv-SE',{timeZone:'America/Los_Angeles'})}｜${types[l.type]}\n- 表达：${n.title}\n- 标签：${Object.entries(dimensions).map(([d,label])=>label+'：'+l.tags[d].join('、')).join('；')}\n${l.type!=='instant'?'- 场景：'+l.context+'\n':''}${l.type==='workplace'?'- 提问：'+l.cn+'\n- 沟通思路：'+l.reason+'\n':''}- 中文表达：${l.suggestion}\n${l.type==='advanced'?'- 基础表达：'+l.comparison.sentenceEn+'\n':''}${l.type==='workplace'?(englishVersion==='professional'?'- 专业版：'+l.pro:'- 口语版：'+l.casual):'- 英文表达：'+(l.picture?u.term:l.casual)}\n- 学习：${u.term} ${u.pronunciation||''}；${u.meaning}\n- 为什么这样说：${l.explain.replace(/这句本身是中性表达，可用于专业和一般对话；两版相同时无需刻意改写。/g,'').replace(/ 原始 Equivalent 仅作为学习线索；是否能替换要看当前含义和语境。/g,'').trim()}\n- 语境变化：${l.variant}\n- 直译改进：${l.fix}`;}
function updateBookmark(){const marked=!!state[current]?.marked;$('#master').textContent=marked?'已标记 ✓':'标记这个表达';$('#master').setAttribute('aria-pressed',String(marked));}
$('#master').onclick=()=>{const previous=state[current],marked=!previous?.marked;state[current]={...previous,marked,markedAt:marked?Date.now():null};if(!save()){if(previous)state[current]=previous;else delete state[current];return}if(view==='browse'){page=Math.floor(filtered().findIndex(l=>l.id===current)/15);render()}else updateBookmark();$('#status').textContent=marked?'已标记，浏览与搜索时优先显示。':'已取消标记。';};
function entryUrl(l){const url=new URL(location.pathname,location.origin);url.hash='entry='+encodeURIComponent(l.id);return url.href;}
function shareText(l){const unit=learning[l.id];return [types[l.type],l.picture?unit.meaning:l.suggestion,l.picture?unit.term:l.casual].join('\n');}
function openExport(mode){const l=currentLesson(),sharing=mode==='share';$('#exportTitle').textContent=sharing?'分享到微信':'复制这个表达';$('#exportHelp').textContent=sharing?'当前浏览器未能打开系统分享面板。复制下面的内容与链接，到微信选择联系人或朋友圈粘贴分享。':'以下是将复制的 Markdown 内容，可直接粘贴到表达日志。';$('#exportContent').textContent=sharing?shareText(l)+'\n\n'+entryUrl(l):log(l);$('#exportCopy').textContent=sharing?'复制分享内容':'复制 Markdown';$('#exportStatus').textContent='';$('#exportDialog').showModal();}
$('#copy').onclick=()=>openExport('copy');
$('#shareExpression').onclick=async()=>{const l=currentLesson(),data={title:'脱口而出 · '+types[l.type],text:shareText(l),url:entryUrl(l)};if(typeof navigator.share==='function'){try{$('#status').textContent='请在手机系统分享面板中选择微信。';await navigator.share(data);$('#status').textContent='已调用系统分享面板。';return}catch(e){if(e.name==='AbortError'){$('#status').textContent='已取消分享。';return}}}openExport('share');};
$('#exportCopy').onclick=async()=>{try{await navigator.clipboard.writeText($('#exportContent').textContent);$('#exportStatus').textContent='已复制。'}catch{const selection=window.getSelection(),range=document.createRange();range.selectNodeContents($('#exportContent'));selection.removeAllRanges();selection.addRange(range);$('#exportStatus').textContent='未能自动复制，已选中内容，请长按或使用复制快捷键。';}};
for(const id of ['closeExport','exportDone'])$('#'+id).onclick=()=>$('#exportDialog').close();
$('#exportDialog').addEventListener('click',e=>{const d=$('#exportDialog'),r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close()});
function openSharedEntry(){const id=new URLSearchParams(location.hash.slice(1)).get('entry'),l=lessons.find(x=>x.id===id);if(!l)return false;resetFilters();$('#typeFilter').value=l.type;current=l.id;navigate('practice');page=Math.floor(filtered().findIndex(x=>x.id===id)/15);render();return true;}
window.addEventListener('hashchange',()=>{if(lessons.length)openSharedEntry()});
for(const d of ['meaning','example','forms','alternatives'])$('#'+d+'Tab').onclick=()=>setStudy(d);
for(const k of ['explain','variant','fix'])$('#'+k+'NoteTab').onclick=()=>setNote(k);
for(const v of ['professional','casual'])$('#'+v+'Tab').onclick=()=>applyVersion(v);
for(const id of ['typeFilter','topicFilter','progress'])$('#'+id).addEventListener('change',()=>{page=0;render()});
for(const type of Object.keys(types))$('#home-'+type).onclick=()=>start(type);
$('#prevPage').onclick=()=>{page--;render()};$('#nextPage').onclick=()=>{page++;render()};$('#backHome').onclick=()=>navigate('home');$('#browse').onclick=()=>browse(true);$('#browseFromPractice').onclick=()=>browse(true);
document.querySelectorAll('[data-practice-action]').forEach(b=>b.onclick=()=>changePractice(b.dataset.practiceAction));
$('#closeLearning').onclick=()=>$('#learningDialog').close();$('#learningDialog').addEventListener('click',e=>{const d=$('#learningDialog'),r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close()});
Promise.all([fetch('data.json').then(r=>{if(!r.ok)throw Error('词条载入失败');return r.json()}),fetch('learning.json').then(r=>{if(!r.ok)throw Error('学习内容载入失败');return r.json()})]).then(([data,units])=>{lessons=data.lessons;learning=units;natives=Object.fromEntries(data.nativeEntries.map(n=>[n.id,n]));for(const type of Object.keys(types))$('#total-'+type).textContent=lessons.filter(l=>l.type===type).length+' 个词条';$('#coverage').textContent=`${lessons.length} 则练习`;if(!openSharedEntry())render();$('#loading').hidden=true;}).catch(e=>{$('#loading').textContent=e.message+'，请刷新重试。'});
